  CONSTRAINT "subscriptions_status_check"
    CHECK
    ((status = ANY (ARRAY['draft'::text, 'pending_payment'::text, 'under_review'::text, 'trialing'::text, 'active'::text, 'past_due'::text, 'paused'::text, 'canceled'::text,
